using System.IO;using System.Reflection;using System.Text.Json;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;
using RAWSelectionAssistant.Core.Services.Projects;using RAWSelectionAssistant.ViewModels;using RAWSelectionAssistant.Views;using RAWSelectionAssistant.Services;
using static RAWSelectionAssistant.WpfTests.RuntimeCorrectionWpfTests;
namespace RAWSelectionAssistant.WpfTests;
[TestClass][DoNotParallelize]public sealed class R54HomeDesignFixTests
{
 static void Layout(FrameworkElement v,int w=1366){v.Measure(new Size(w,w==1366?768:1080));v.Arrange(new Rect(0,0,w,w==1366?768:1080));v.UpdateLayout();}
 static void Invoke(PhotoGradePageView v,string method){var m=typeof(PhotoGradePageView).GetMethod(method,BindingFlags.NonPublic|BindingFlags.Instance)!;m.Invoke(v,m.GetParameters().Length==0?null:[v,new RoutedEventArgs()]);}
 static async Task Settle(TetherReferenceModeViewModel e){var until=DateTime.UtcNow.AddSeconds(30);while(!e.IsSettled&&DateTime.UtcNow<until)await Task.Delay(20);Assert.IsTrue(e.IsSettled,e.StatusText);}
 static string Image(string root){Directory.CreateDirectory(root);var bytes=new byte[120*80*3];for(int i=0;i<bytes.Length;i+=3){bytes[i]=(byte)(80+i%120);bytes[i+1]=90;bytes[i+2]=40;}var image=BitmapSource.Create(120,80,96,96,PixelFormats.Rgb24,null,bytes,360);var enc=new PngBitmapEncoder();enc.Frames.Add(BitmapFrame.Create(image));var p=Path.Combine(root,"home-ui-synthetic.png");using var f=File.Create(p);enc.Save(f);return p;}
 static string PixelHash(BitmapSource image){var format=new FormatConvertedBitmap(image,PixelFormats.Bgra32,null,0);var bytes=new byte[format.PixelWidth*format.PixelHeight*4];format.CopyPixels(bytes,format.PixelWidth*4,0);return Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(bytes));}
 static void Capture(FrameworkElement v,string root,string name){v.UpdateLayout();var bitmap=new RenderTargetBitmap((int)v.ActualWidth,(int)v.ActualHeight,96,96,PixelFormats.Pbgra32);bitmap.Render(v);var enc=new PngBitmapEncoder();enc.Frames.Add(BitmapFrame.Create(bitmap));using var f=File.Create(Path.Combine(root,name+"-OFFSCREEN.png"));enc.Save(f);}
 static IEnumerable<T> Desc<T>(DependencyObject x)where T:DependencyObject{if(x is T t)yield return t;for(int i=0;i<VisualTreeHelper.GetChildrenCount(x);i++)foreach(var child in Desc<T>(VisualTreeHelper.GetChild(x,i)))yield return child;}
 [TestMethod]public Task ExistingColorToolsGroupAndMaskUseSelectedNode()=>RunSta(async()=>
 {
  var root=Environment.GetEnvironmentVariable("KITAO_R54_HOME_FIX")??throw new InvalidOperationException("Explicit isolated evidence root required");EnsureTestApplication();using var vm=new ReferenceColorWorkspaceViewModel(new Dialogs());await vm.LoadTargetAsync(Image(root));await vm.CreateR53VariantAsync(true);
  var e=vm.Editor;foreach(var type in new[]{"BasicTone","Levels","ColorBalance","SkinTone","Details","ColorRange","Curve"})e.AddAdjustmentNodeCommand.Execute(type);
  var names=new Dictionary<ColorStudioNodeType,string>{{ColorStudioNodeType.Levels,"色阶"},{ColorStudioNodeType.ColorBalance,"色彩平衡"},{ColorStudioNodeType.SkinTone,"肤色均匀化"},{ColorStudioNodeType.Details,"细节"},{ColorStudioNodeType.ColorRange,"颜色范围"}};
  foreach(var item in names)Assert.AreEqual(item.Value,e.AdjustmentNodes.Last(n=>n.Type==item.Key).Name);
  var levels=e.AdjustmentNodes.First(n=>n.Type==ColorStudioNodeType.Levels);e.SelectedAdjustmentNode=levels;e.SelectedNodeName="我的自定义名称";Assert.AreEqual("我的自定义名称",e.SelectedAdjustmentNode!.Name);
  var range=e.AdjustmentNodes.Last(n=>n.Type==ColorStudioNodeType.ColorRange);e.SelectedAdjustmentNode=range;await Settle(e);var page=new PhotoGradePageView{DataContext=vm};Layout(page);vm.R53Professional=true;page.SelectClosureNodeTool("HSL");Invoke(page,"OpenR53Panel");page.ApplyR53Layout();Layout(page);
  var stack=(StackPanel)((ScrollViewer)page.FindName("AdjustmentScroll")).Content;var section=stack.Children.OfType<Expander>().Single(x=>Equals(x.Tag,"AdjustmentScroll.ColorRange"));Assert.AreEqual(Visibility.Visible,section.Visibility);Assert.AreEqual(7,Desc<Slider>(section).Count());Assert.IsTrue(section.Header!.ToString()!.Contains("旧版"));
  var rangeId=range.Id;e.RangeHue=35;Assert.AreEqual(rangeId,e.SelectedAdjustmentNode!.Id);Assert.AreEqual(35,e.RangeHue);e.UndoAdjustmentCommand.Execute(null);Assert.AreEqual(0,e.RangeHue);e.RedoAdjustmentCommand.Execute(null);Assert.AreEqual(35,e.RangeHue);
  e.StartSamplingCommand.Execute("普通取样");await (Task)typeof(PhotoGradePageView).GetMethod("SampleR54ColorAsync",BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(page,[new Point(((FrameworkElement)page.FindName("PhotoViewport")).ActualWidth/2,((FrameworkElement)page.FindName("PhotoViewport")).ActualHeight/2)])!;Assert.AreEqual(rangeId,e.SelectedAdjustmentNode!.Id);Assert.IsTrue(e.PositiveSamples.Count>0);await Settle(e);var rangeBefore=PixelHash(e.MatchedImage!);e.RangeHue=-80;await Settle(e);Assert.AreNotEqual(rangeBefore,PixelHash(e.MatchedImage!),"Existing range tool must alter actual pixels");Capture(page,root,"range");
  var skin=e.AdjustmentNodes.Last(n=>n.Type==ColorStudioNodeType.SkinTone);e.SelectedAdjustmentNode=skin;page.ApplyR53Layout();Layout(page);var skinSection=stack.Children.OfType<Expander>().Single(x=>Equals(x.Tag,"AdjustmentScroll.8"));Assert.AreEqual(Visibility.Visible,skinSection.Visibility);Assert.AreEqual(9,Desc<Slider>(skinSection).Count());var skinParam=ColorStudioToolCatalog.GetParameters(ColorStudioNodeType.SkinTone).Single(p=>p.Key=="hue_uniformity");var skinBefore=PixelHash(e.MatchedImage!);e.SetToolParameter(skinParam,100);await Settle(e);Assert.AreNotEqual(skinBefore,PixelHash(e.MatchedImage!),"Existing skin parameter must alter actual pixels");Assert.AreEqual(100,e.ToolValue(skinParam));Assert.AreEqual(skin.Id,e.SelectedAdjustmentNode!.Id);await Settle(e);Capture(page,root,"skin");
  var curve=e.AdjustmentNodes.Last(n=>n.Type==ColorStudioNodeType.Curve);e.SelectedAdjustmentNode=curve;e.AddMaskStroke(new([new(.5,.5)],.2,.5,1,1));Assert.IsTrue(e.AddParallelGraphBranch(),e.StatusText);await Settle(e);Layout(page);vm.Layout=vm.Layout with{R54GraphCollapsed=false};page.DataContext=null;page.DataContext=vm;Layout(page);Invoke(page,"OpenR53Panel");page.ApplyR53Layout();
  var graph=(StudioNodeGraphView)((Grid)page.FindName("R53NodeContent")).Children[0];var pos=e.GraphView.Positions.Single(p=>p.NodeId==curve.Id);Assert.IsTrue(graph.TryOpenMaskAt(new Point(pos.X+100,pos.Y+35)));Assert.AreEqual(curve.Id,e.SelectedAdjustmentNode!.Id);Assert.AreEqual(2,((TabControl)page.FindName("EditModes")).SelectedIndex);e.SelectedNodeLocked=true;var saved=JsonSerializer.Serialize(e.AdjustmentStack);Assert.IsTrue(graph.TryOpenMaskAt(new Point(pos.X+100,pos.Y+35)));e.AddMaskStroke(new([new(.6,.6)],.2,.5,1,1));Assert.AreEqual(saved,JsonSerializer.Serialize(e.AdjustmentStack));e.SelectedNodeLocked=false;Invoke(page,"R53Professional");Assert.AreEqual(curve.Id,e.SelectedAdjustmentNode!.Id);
  vm.R53Professional=false;((TabControl)page.FindName("EditModes")).SelectedIndex=0;page.ApplyR53Layout();Layout(page);var group=(StackPanel)((Expander)page.FindName("R53SimpleLayers")).Content;var row=group.Children.OfType<Border>().Single(x=>x.Height==38);Assert.AreEqual(Visibility.Visible,row.Visibility);var before=JsonSerializer.Serialize(e.AdjustmentStack.Graph!.Edges);e.SelectedAdjustmentNode=e.AdjustmentNodes.First(n=>n.Type==ColorStudioNodeType.BasicTone);Assert.IsTrue(e.AddGraphSerialNode("ColorRange"));Assert.AreEqual(ColorStudioNodeType.ColorRange,e.SelectedAdjustmentNode!.Type);e.UndoAdjustmentCommand.Execute(null);Assert.AreEqual(before,JsonSerializer.Serialize(e.AdjustmentStack.Graph!.Edges));e.ProfessionalGroupAmount=.5;vm.R53Professional=true;Assert.AreEqual(before,JsonSerializer.Serialize(e.AdjustmentStack.Graph!.Edges));vm.R53Professional=false;page.ApplyR53Layout();Capture(page,root,"group");
  await Settle(e);var project=Path.Combine(root,"selected-tools.ptstudio.json");await vm.SaveSessionAsync(project);Assert.IsTrue(File.Exists(project));await File.WriteAllTextAsync(Path.Combine(root,"expected-home.json"),JsonSerializer.Serialize(new{pid=Environment.ProcessId,project,stack=JsonSerializer.Serialize(e.AdjustmentStack),pixelHash=PixelHash(e.MatchedImage!)}));page.DataContext=null;
 });
 [TestMethod]public Task IndependentReopenRetainsSelectedToolsGraphAndPixels()=>RunSta(async()=>
 {
  var root=Environment.GetEnvironmentVariable("KITAO_R54_HOME_FIX")??throw new InvalidOperationException("Explicit isolated evidence root required");var expected=JsonDocument.Parse(await File.ReadAllTextAsync(Path.Combine(root,"expected-home.json"))).RootElement;Assert.AreNotEqual(expected.GetProperty("pid").GetInt32(),Environment.ProcessId);EnsureTestApplication();using var vm=new ReferenceColorWorkspaceViewModel(new Dialogs());await vm.LoadSessionAsync(expected.GetProperty("project").GetString()!);await Settle(vm.Editor);Assert.AreEqual(expected.GetProperty("stack").GetString(),JsonSerializer.Serialize(vm.Editor.AdjustmentStack));Assert.AreEqual(expected.GetProperty("pixelHash").GetString(),PixelHash(vm.Editor.MatchedImage!));Assert.IsTrue(vm.Editor.AdjustmentNodes.Any(n=>n.Name=="我的自定义名称"));await File.WriteAllTextAsync(Path.Combine(root,"reopen-home.json"),JsonSerializer.Serialize(new{pid=Environment.ProcessId,stackExact=true,pixelsExact=true,scope="independent testhost"}));
 });
